insert into public.quiz_questions (mode, step, question, options, correct, explanation)
values
('island', 1, 'Wie heißt die Hauptstadt von Gran Canaria?', '["Maspalomas", "Las Palmas de Gran Canaria", "Santa Cruz de Tenerife", "Telde"]'::jsonb, 1, 'Las Palmas de Gran Canaria, kurz „Las Palmas“, liegt im Nordosten der Insel.'),
('island', 1, 'Zu welchem Land gehören die Kanaren?', '["Portugal", "Frankreich", "Spanien", "Marokko"]'::jsonb, 2, 'Spanien – die Kanaren sind eine autonome Gemeinschaft mit eigener Regierung in Santa Cruz de Tenerife und Las Palmas.'),
('island', 1, 'Welche Sprache spricht man auf Gran Canaria?', '["Portugiesisch", "Italienisch", "Französisch", "Spanisch"]'::jsonb, 3, 'Spanisch, genauer der kanarische Dialekt – man duzt hier traditionell auch Fremde, das „tú“ ist normal.'),
('island', 1, 'Welche Währung gilt auf den Kanaren?', '["Euro", "Kanarische Krone", "Dollar", "Peseta"]'::jsonb, 0, 'Euro. Die Kanaren sind EU-Gebiet, aber nicht im Zollgebiet der EU.'),
('island', 1, 'Wie heißt der berühmte Fels im Inselinneren?', '["El Teide", "Roque Nublo", "Dedo de Dios", "Montserrat"]'::jsonb, 1, 'Der Roque Nublo ist das Wahrzeichen der Insel – ein 80 Meter hoher Basaltfelsen auf 1.813 Metern.'),
('island', 1, 'Wie heißt die Nachbarinsel westlich von Gran Canaria?', '["Lanzarote", "Fuerteventura", "Teneriffa", "La Gomera"]'::jsonb, 2, 'Teneriffa mit dem Teide (3.718 m). Fuerteventura liegt im Osten.'),
('island', 1, 'Wo liegt Gran Canaria?', '["Mittelmeer", "Vor Portugal", "Karibik", "Vor der Küste Marokkos"]'::jsonb, 3, 'Rund 210 Kilometer westlich der marokkanischen Küste, auf der Afrikanischen Platte.'),
('island', 1, 'Wie heißen die großen Dünen im Süden?', '["Dünen von Maspalomas", "Dünen von Arinaga", "Dünen von Amadores", "Dünen von las Canteras"]'::jsonb, 0, 'Die Dünen von Maspalomas sind Naturschutzgebiet und wandern mit dem Wind langsam weiter.'),
('island', 1, 'Was sind „papas arrugadas“?', '["Frittierte Fischstücke", "In Salzwasser gekochte Kartoffeln", "Gefüllte Paprika", "Ein Käse"]'::jsonb, 1, 'Kleine Kartoffeln, in sehr salzigem Wasser gekocht – die Schale runzelt (daher der Name).'),
('island', 1, 'Wie kommt man am schnellsten nach Teneriffa?', '["Mit dem Zug", "Über den Flughafen nur mit Umweg", "Mit der Fähre", "Mit der Seilbahn"]'::jsonb, 2, 'Fähre ab Agaete (Fred. Olsen) oder ab Las Palmas, rund 80 Minuten.'),
('island', 1, 'Womit fährt man auf der Insel am besten ins Bergdorf?', '["Mit der Bahn", "Nur mit dem Taxi", "Nur zu Fuß", "Mit dem Bus oder Auto"]'::jsonb, 3, 'Ein Zug auf die Insel existiert bis heute nicht; Busse heißen hier „guaguas“.'),
('island', 1, 'Welche Farbe hat der Sand in den Dünen von Maspalomas?', '["Goldbraun", "Weiß", "Rot", "Schwarz"]'::jsonb, 0, 'Goldbrauner Sand, der von den Passatwinden aus der Sahara und vom Strand herangetragen wird.'),
('island', 2, 'Wie viele große Inseln gehören zu den Kanaren?', '["5", "6", "7", "9"]'::jsonb, 2, 'Sieben große: El Hierro, La Palma, La Gomera, Teneriffa, Gran Canaria, Fuerteventura und Lanzarote. La Graciosa ist seit 2018 die achte bewohnte.'),
('island', 2, 'Welcher Berg ist der höchste Spaniens?', '["Roque Nublo", "Pico de las Nieves", "Mulhacén", "Teide"]'::jsonb, 3, 'Der Teide auf Teneriffa mit 3.718 Metern – auch der höchste Berg auf spanischem Boden.'),
('island', 2, 'Wie heißt die rundliche Form der Insel auf der Karte?', '["Fast kreisförmig", "Dreieckig", "Lang und schmal", "Herzförmig"]'::jsonb, 0, 'Gran Canaria ist fast kreisrund, rund 50 Kilometer im Durchmesser.'),
('island', 2, 'Wie heißen die tiefen Trockentäler der Insel?', '["Ramblas", "Barrancos", "Calderas", "Valles"]'::jsonb, 1, 'Barrancos. Bei seltenem Starkregen führen sie reißende Sturzbäche.'),
('island', 2, 'Was ist „gofio“?', '["Ein Fischgericht", "Ein Käse", "Geröstetes Getreidemehl", "Ein Wein"]'::jsonb, 2, 'Gofio war das Grundnahrungsmittel der Inselbewohner – geröstetes, gemahlenes Getreide, heute in Milch oder Eintopf.'),
('island', 2, 'Wie heißen die Saucen zu den Kartoffeln?', '["Salsas", "Chimichurris", "Aliolis", "Mojos"]'::jsonb, 3, 'Mojo rojo (scharf, rot) und Mojo verde (grün, mit Koriander).'),
('island', 2, 'In welchem Ort steht das Wahrzeichen mit den zwei Felsenbuchten im Norden?', '["Las Palmas", "Agaete", "Puerto de Mogán", "Arucas"]'::jsonb, 0, 'Die Playa de las Canteras in Las Palmas gilt als eine der besten Stadtstrände Europas.'),
('island', 2, 'Welche Frucht wird auf der Insel in großen Mengen angebaut?', '["Äpfel", "Bananen", "Kirschen", "Datteln"]'::jsonb, 1, '„Plátano de Canarias“ – die kleinen, aromatischen Bananen mit geschützter Herkunftsbezeichnung.'),
('island', 2, 'Wie heißt der größte Hafen der Insel?', '["Arinaga", "Puerto Rico", "Puerto de la Luz", "Mogán"]'::jsonb, 2, 'Der Puerto de la Luz in Las Palmas – einer der wichtigsten Atlantikhäfen mit riesigem Umschlag.'),
('island', 2, 'Was bedeutet „calima“?', '["Ein Regenguss", "Ein Brand", "Ein Erdbeben", "Saharastaub in der Luft"]'::jsonb, 3, 'Heißer Wind aus der Sahara mit Staub – die Sicht wird milchig, die Temperatur steigt deutlich.'),
('island', 2, 'Welche Stadt liegt im Nordwesten und ist für ihre Kirche bekannt?', '["Teror", "Mogán", "Agüimes", "Fataga"]'::jsonb, 0, 'Teror mit der Basilika Nuestra Señora del Pino – die Schutzpatronin der Insel.'),
('island', 2, 'Wie heißt der Ort mit den berühmten Höhlenwohnungen im Süden?', '["Temisas", "Guayadeque", "Artenara", "Tejeda"]'::jsonb, 1, 'Im Barranco de Guayadeque liegen Wohnhöhlen und Restaurants direkt im Fels.'),
('island', 3, 'Welcher ist der höchste Berg der Insel?', '["Teide", "Pico de las Nieves", "Roque Nublo", "Morro de la Agujereada"]'::jsonb, 3, 'Der Morro de la Agujereada mit 1.956 Metern – der Pico de las Nieves daneben ist mit 1.949 Metern der zweithöchste.'),
('island', 3, 'Wie groß ist Gran Canaria?', '["1.560 km²", "620 km²", "2.400 km²", "3.000 km²"]'::jsonb, 0, '1.560 km² – damit die drittgrößte der Kanaren nach Teneriffa und Fuerteventura.'),
('island', 3, 'Wie viele Einwohner hat die Insel etwa?', '["180.000", "860.000", "430.000", "1,5 Mio."]'::jsonb, 1, 'Rund 864.000 (2024) – davon etwa die Hälfte in Las Palmas und Umgebung.'),
('island', 3, 'Was bedeutet der Name „Las Palmas“ wörtlich?', '["Die Strände", "Die Häfen", "Die Palmen", "Die Dünen"]'::jsonb, 2, 'Palmen. Der vollständige Name lautet Las Palmas de Gran Canaria.'),
('island', 3, 'Welches Tier ist auf der Insel weit verbreitet und endemisch?', '["Der Igel", "Der Luchs", "Das Murmeltier", "Die Kanareneidechse"]'::jsonb, 3, 'Gallotia stehlini, die Kanareneidechse – sie sonnt sich auf Mauern und Steinen.'),
('island', 3, 'Wie heißt der Vulkankrater nahe Las Palmas?', '["Caldera de Bandama", "Caldera de Taburiente", "Caldera de Tejeda", "Krater von Fataga"]'::jsonb, 0, 'Die Caldera de Bandama – rund 1.000 Meter im Durchmesser und 200 Meter tief.'),
('island', 3, 'Was ist der „Roque“ in Ortsnamen wie Roque Nublo?', '["Ein Wald", "Ein Fels", "Ein Bach", "Ein Dorf"]'::jsonb, 1, 'Roque heißt Fels – im Kanarischen sind es oft Basaltfelsen oder Felskegel.'),
('island', 3, 'Wie heißt der Flughafen der Insel?', '["Teneriffa Nord", "Las Palmas Sur", "Gran Canaria", "Maspalomas"]'::jsonb, 2, 'Flughafen Gran Canaria, Kürzel LPA, in der Bucht von Gando.'),
('island', 3, 'Wann blühen die Mandelbäume im Inselinneren?', '["Im Oktober", "Im Juli", "Im Mai", "Im Februar"]'::jsonb, 3, 'Rund um Tejeda im Februar – dann feiert man dort das Mandelblütenfest.'),
('island', 3, 'Welche Bäume prägen die Bergwälder?', '["Kanarische Kiefern", "Eichen", "Buchen", "Birken"]'::jsonb, 0, 'Pinus canariensis – sehr feuerfest, treibt nach Bränden aus dem Stamm wieder aus.'),
('island', 3, 'Was ist eine „guagua“?', '["Ein Boot", "Der Bus", "Ein Kuchen", "Ein Lied"]'::jsonb, 1, 'Das kanarische Wort für Bus – stammt vermutlich aus dem Kubanischen.'),
('island', 3, 'Wie heißt der Ort mit der berühmten Rum-Brennerei?', '["San Mateo", "Agaete", "Arucas", "Santa Brígida"]'::jsonb, 2, 'Arucas – dort steht die Brennerei Arehucas und die neugotische Kirche San Juan Bautista.'),
('island', 4, 'Wie tief ist die Caldera de Bandama?', '["200 m", "80 m", "450 m", "700 m"]'::jsonb, 0, 'Rund 200 Meter tief, 1.000 Meter breit. Der Pico de Bandama daneben ist 569 Meter hoch.'),
('island', 4, 'Welche Insel liegt östlich von Gran Canaria?', '["La Palma", "Fuerteventura", "El Hierro", "La Gomera"]'::jsonb, 1, 'Fuerteventura – man sieht sie an klaren Tagen von den Höhen aus.'),
('island', 4, 'Was ist ein „barranco“?', '["Ein Strand", "Ein Marktplatz", "Ein Trockental", "Ein Gipfel"]'::jsonb, 2, 'Ein von Wasser geformtes Tal; viele führen nur bei Starkregen Wasser.'),
('island', 4, 'Wie heißt die alte Altstadt von Las Palmas?', '["Triana", "Arenales", "Guanarteme", "Vegueta"]'::jsonb, 3, 'Vegueta – der Gründungsort von 1478 mit Kathedrale Santa Ana und Casa de Colón.'),
('island', 4, 'Was wird in Temisas angebaut?', '["Oliven", "Wein", "Kaffee", "Baumwolle"]'::jsonb, 0, 'Im Tal von Temisas liegt der größte Olivenhain des Archipels; das Öl heißt „Caserío de Temisas“.'),
('island', 4, 'Auf welcher Höhe liegt Temisas?', '["Etwa 350 m", "Etwa 690 m", "Etwa 1.100 m", "Etwa 1.800 m"]'::jsonb, 1, 'Rund 687 Meter – deshalb ist es dort oben oft einige Grad kühler als an der Küste.'),
('island', 4, 'Welche Stadt liegt am Meer und ist für ihren Fischerhafen bekannt?', '["Tejeda", "Artenara", "Mogán", "San Bartolomé"]'::jsonb, 2, 'Puerto de Mogán im Südwesten – kleine Kanäle, Boote und ein Hafen.'),
('island', 4, 'Was ist „aloe vera“ auf der Insel?', '["Ein Wein", "Ein Vulkan", "Ein Fisch", "Eine Heilpflanze"]'::jsonb, 3, 'Aloe wird auf Gran Canaria großflächig angebaut und zu Kosmetik und Saft verarbeitet.'),
('island', 4, 'Wie heißt die Hochebene um Tejeda?', '["Caldera de Tejeda", "Valle de Agaete", "Llanos de Maspalomas", "Meseta de Fataga"]'::jsonb, 0, 'Die Caldera de Tejeda ist ein eingebrochener Vulkan mit rund 15 Kilometer Durchmesser.'),
('island', 4, 'Welche Farbe hat der kanarische Mojo verde?', '["Rot", "Grün", "Gelb", "Schwarz"]'::jsonb, 1, 'Grün vom Koriander (oder Petersilie); Mojo rojo wird mit getrockneten Chilis gemacht.'),
('island', 4, 'Wann ist der höchste Feiertag der Kanaren?', '["12. Oktober", "1. Januar", "30. Mai", "1. Mai"]'::jsonb, 2, 'Der 30. Mai ist „Día de Canarias“ – Feiertag auf allen Inseln.'),
('island', 4, 'Wie heißt das Dorf im Süden mit Palmen im Tal?', '["Firgas", "Artenara", "Teror", "Fataga"]'::jsonb, 3, 'Fataga liegt in einem Palmental an der Straße von Maspalomas ins Bergland.'),
('island', 5, 'Welchen Berg sieht man bei klarer Sicht am Horizont?', '["Fuerteventuras Vulkane", "Den Teide auf Teneriffa", "Die Berge von La Gomera", "Madeiras Gipfel"]'::jsonb, 1, 'Vom Pico de las Nieves aus ist der Teide bei klarer Luft am Horizont zu erkennen – 60 km entfernt.'),
('island', 5, 'Wie alt ist die Insel geologisch ungefähr?', '["1,5 Mio. Jahre", "80 Mio. Jahre", "14,5 Mio. Jahre", "300 Mio. Jahre"]'::jsonb, 2, 'Rund 14,5 Millionen Jahre – die ältesten Gesteine liegen im Südwesten.'),
('island', 5, 'Wann brach der letzte Vulkan auf der Insel aus?', '["Vor 20.000 Jahren", "Vor 200 Jahren", "Er ist noch aktiv", "Vor 2.000 Jahren"]'::jsonb, 3, 'Die letzte Eruption war die von Bandama vor rund 2.000 Jahren.'),
('island', 5, 'Wie hoch ist der Roque Nublo?', '["1.813 m", "1.600 m", "2.100 m", "1.200 m"]'::jsonb, 0, 'Der Gipfel liegt auf 1.813 Metern; der Fels selbst ragt etwa 80 Meter aus dem Sattel.'),
('island', 5, 'Welche Pflanze liefert den roten Farbstoff, mit dem die Insel früher handelte?', '["Indigo", "Koschenille", "Krapp", "Safran"]'::jsonb, 1, 'Die Cochenille-Schildlaus auf Feigenkakteen – im 19. Jahrhundert wichtigster Export.'),
('island', 5, 'Wie heißt das Schutzgebiet im Südwesten mit Kiefernwald?', '["Tamadaba", "Pilancones", "Alle drei", "Inagua"]'::jsonb, 2, 'Alle drei sind Naturparks im Südwesten; zusammen bilden sie einen großen Waldgürtel.'),
('island', 5, 'Was ist ein „mirador“?', '["Ein Brunnen", "Ein Hotel", "Ein Parkplatz", "Ein Aussichtspunkt"]'::jsonb, 3, 'Aussichtspunkt – an der Straße ins Gebirge gibt es viele davon.'),
('island', 5, 'Welches Meer umgibt die Insel?', '["Atlantik", "Nordsee", "Rotes Meer", "Mittelmeer"]'::jsonb, 0, 'Atlantik – mit Passatwinden, die den Norden feucht und den Süden trocken machen.'),
('island', 5, 'Warum ist der Norden grüner als der Süden?', '["Mehr Flüsse", "Passatwolken regnen dort ab", "Mehr Bewässerung", "Höhere Lage"]'::jsonb, 1, 'Die Passatwinde stauen sich an den Bergen, der Norden bekommt Nebel und Regen, der Süden bleibt trocken.'),
('island', 5, 'Wie heißt der Ort mit den Kanälen und dem kleinen Strand im Südwesten?', '["Puerto Rico", "Arguineguín", "Puerto de Mogán", "Playa del Cura"]'::jsonb, 2, 'Puerto de Mogán – „Klein-Venedig“ genannt, mit Kanälen und Fischerbooten.'),
('island', 5, 'Welcher Käse ist auf den Kanaren typisch?', '["Gouda", "Parmesan", "Feta", "Queso de flor"]'::jsonb, 3, 'Queso de flor – mit der Blüte der Artischockendistel hergestellt, auf Gran Canaria eine Spezialität.'),
('island', 5, 'Wie heißt der höchste Ort der Insel?', '["Artenara", "Tejeda", "Temisas", "San Mateo"]'::jsonb, 0, 'Artenara liegt auf rund 1.270 Metern – viele Häuser sind in den Fels gebaut.'),
('island', 6, 'Wer gründete 1478 die Stadt Las Palmas?', '["Fernando Guanarteme", "Pedro de Vera", "Juan Rejón", "Christoph Kolumbus"]'::jsonb, 2, 'Juan Rejón landete am 24. Juni 1478 an der Mündung des Barranco de Guiniguada – dort liegt heute Vegueta.'),
('island', 6, 'In welchem Jahr war die Eroberung der Insel abgeschlossen?', '["1478", "1502", "1492", "1483"]'::jsonb, 3, 'Pedro de Vera unterwarf 1483 die letzten Widerstandsnester bei Gáldar.'),
('island', 6, 'Wie nennt man die Ureinwohner Gran Canarias?', '["Canarios", "Bimbaches", "Guanches", "Arucas"]'::jsonb, 0, 'Canarios – „Guanches“ sind die Ureinwohner Teneriffas. Die Bezeichnungen werden oft verwechselt.'),
('island', 6, 'Wie heißt die bemalte Höhle bei Gáldar?', '["Cueva de los Verdes", "Cueva Pintada", "Cueva de Guayadeque", "Cueva del Rey"]'::jsonb, 1, 'Die Cueva Pintada ist für ihre geometrischen Wandmalereien berühmt und heute Museum.'),
('island', 6, 'Welches Haus in Las Palmas erinnert an Kolumbus?', '["Palacio Episcopal", "Casa de Vera", "Casa de Colón", "Casa de la Cultura"]'::jsonb, 2, 'Kolumbus stoppte 1492 auf dem Weg nach Amerika, um das Ruder der „Pinta“ reparieren zu lassen.'),
('island', 6, 'Welche Kirche steht im Zentrum von Vegueta?', '["San Juan Bautista", "Iglesia de San Telmo", "Basílica del Pino", "Kathedrale Santa Ana"]'::jsonb, 3, 'Die Kathedrale Santa Ana – 1497 begonnen und über Jahrhunderte weitergebaut.'),
('island', 6, 'Wie viele Gemeinden hat Gran Canaria?', '["21", "18", "14", "27"]'::jsonb, 0, '21 Municipios – Temisas gehört zur Gemeinde Agüimes.'),
('island', 6, 'Wie heißt die Autobahn entlang der Ostküste?', '["A-7", "GC-1", "GC-60", "TF-1"]'::jsonb, 1, 'Die GC-1 führt von Las Palmas über den Flughafen bis nach Mogán.'),
('island', 6, 'Was ist ein „almogarén“?', '["Ein Hafen", "Ein Bauernhaus", "Eine Kultstätte der Ureinwohner", "Eine Zisterne"]'::jsonb, 2, 'Heilige Stätten unter freiem Himmel – der Roque Bentayga ist die bekannteste.'),
('island', 6, 'Welches Getränk wird aus Zuckerrohr gebrannt?', '["Wein", "Cidre", "Bier", "Rum"]'::jsonb, 3, 'Rum – die Brennerei Arehucas in Arucas ist die bekannteste der Kanaren.'),
('island', 6, 'Woher kam die Kartoffel, die hier „papa“ heißt?', '["Aus Südamerika", "Aus Asien", "Aus Afrika", "Aus Europa"]'::jsonb, 0, 'Ursprünglich aus den Anden; über die spanischen Kolonien kam sie auf die Inseln und nach Europa.'),
('island', 6, 'Welches Fest ist das größte in Las Palmas?', '["Die Semana Santa", "Der Karneval", "Das Erntedankfest", "Das Mandelblütenfest"]'::jsonb, 1, 'Der Karneval von Las Palmas zählt zu den größten Spaniens – mit der berühmten Drag-Queen-Gala.'),
('island', 7, 'Seit wann ist Gran Canaria UNESCO-Biosphärenreservat?', '["2019", "1995", "2013", "2005"]'::jsonb, 3, 'Seit 2005 – rund 43 Prozent der Inselfläche gehören dazu, plus ein großer Meeresstreifen.'),
('island', 7, 'Wie viel Prozent der Inselfläche sind Biosphärenreservat?', '["43 %", "23 %", "33 %", "63 %"]'::jsonb, 0, '43 Prozent – der Südwesten mit Tamadaba, Inagua, Pilancones und der Caldera de Tejeda.'),
('island', 7, 'Wer ist die Schutzpatronin der Insel?', '["Virgen del Carmen", "Virgen del Pino", "Santa Ana", "Santa Lucía"]'::jsonb, 1, 'Die Jungfrau vom Pinienbaum in Teror; ihr Fest ist am 8. September.'),
('island', 7, 'Woher stammen die Ureinwohner der Insel?', '["Aus Skandinavien", "Aus Griechenland", "Von den Berbern Nordafrikas", "Aus Südamerika"]'::jsonb, 2, 'Berber vom Beginn unserer Zeitrechnung – Inschriften in libysch-berberischer Schrift belegen es.'),
('island', 7, 'Welcher Widerstandskämpfer der Canarios ist legendär?', '["Bentayga", "Guanarteme", "Tenesor", "Doramas"]'::jsonb, 3, 'Doramas führte den Guerillakampf in den Wäldern – heute nach ihm benannt: das Dorf Doramas und der Parque Doramas.'),
('island', 7, 'Wer war der letzte Herrscher, der sich taufen ließ und Frieden schloss?', '["Fernando Guanarteme", "Doramas", "Pedro de Vera", "Juan Rejón"]'::jsonb, 0, 'Tenesor Semidán, getauft als Fernando Guanarteme – er verhandelte 1483 die Übergabe.'),
('island', 7, 'Welcher Dichter und Schriftsteller wurde in Las Palmas geboren?', '["Miguel de Unamuno", "Benito Pérez Galdós", "Federico García Lorca", "Camilo José Cela"]'::jsonb, 1, 'Galdós (1843–1920), Autor der „Pérez Galdós“-Romane über Madrid – sein Geburtshaus ist Museum.'),
('island', 7, 'Welcher weltberühmte Tenor stammt aus Las Palmas?', '["Plácido Domingo", "Luciano Pavarotti", "Alfredo Kraus", "José Carreras"]'::jsonb, 2, 'Alfredo Kraus (1927–1999); das Auditorium an der Playa de las Canteras trägt seinen Namen.'),
('island', 7, 'Welcher Felsen in Agaete ist als „Finger Gottes“ bekannt?', '["El Fraile", "Roque Nublo", "Roque Bentayga", "Dedo de Dios"]'::jsonb, 3, 'Die Felsnadel „Dedo de Dios“ – ihre Spitze brach 2005 bei einem Sturm ab.'),
('island', 7, 'Wann griff eine niederländische Flotte Las Palmas an?', '["1599", "1499", "1648", "1704"]'::jsonb, 0, '1599 unter Pieter van der Does – die Stadt wurde geplündert, aber nicht dauerhaft eingenommen.'),
('island', 7, 'Welche Insel ist für ihre Pfeifsprache bekannt?', '["Lanzarote", "La Gomera", "El Hierro", "La Palma"]'::jsonb, 1, 'El Silbo Gomero – eine Pfeifsprache, die über die Schluchten trägt und heute in der Schule gelehrt wird.'),
('island', 7, 'Was war der wichtigste Export im 19. Jahrhundert?', '["Bananen", "Salz", "Cochenille-Farbstoff", "Wein"]'::jsonb, 2, 'Der rote Farbstoff der Schildlaus auf Feigenkakteen – bis synthetische Farben ihn verdrängten.'),
('island', 8, 'Seit wann ist Risco Caído UNESCO-Welterbe?', '["2019", "2013", "2005", "2022"]'::jsonb, 0, 'Im Juli 2019 wurde die Kulturlandschaft „Risco Caído und die heiligen Berge“ zum Welterbe erklärt.'),
('island', 8, 'Wie groß ist das Welterbe-Gebiet?', '["5.000 ha", "18.000 ha", "12.000 ha", "40.000 ha"]'::jsonb, 1, 'Rund 18.000 Hektar – etwa elf Prozent der Inselfläche.'),
('island', 8, 'Was war die „Höhle 6“ von Risco Caído?', '["Ein Kornspeicher", "Ein Gefängnis", "Ein astronomischer Kalender", "Eine Zisterne"]'::jsonb, 2, 'Durch eine Öffnung im Fels fällt Licht zu bestimmten Zeiten auf Markierungen – ein Kalender für Sonne und Mond.'),
('island', 8, 'Welcher Fels gehört zu den „heiligen Bergen“?', '["Roque Nublo", "Pico de las Nieves", "Montaña de Arucas", "Roque Bentayga"]'::jsonb, 3, 'Roque Bentayga war Zeremonienplatz; der Roque Nublo ist Wahrzeichen, aber nicht Teil des Welterbes.'),
('island', 8, 'In welchen Gemeinden liegt das Welterbe?', '["Artenara, Tejeda, Agaete, Gáldar", "Maspalomas, Mogán, San Bartolomé", "Las Palmas, Telde, Ingenio", "Agüimes, Santa Lucía, Temisas"]'::jsonb, 0, 'Vier Gemeinden im Nordwesten und Zentrum, rund um die Caldera de Tejeda.'),
('island', 8, 'Wie alt sind die ältesten Spuren der Ureinwohner?', '["Etwa 500 Jahre", "Etwa 2.000 Jahre", "Etwa 10.000 Jahre", "Etwa 50.000 Jahre"]'::jsonb, 1, 'Man geht von rund 2.000 Jahren aus – die Besiedlung begann etwa um Christi Geburt.'),
('island', 8, 'Was bedeutet das Wort „Guanarteme“?', '["Häuptling", "Priester", "König", "Krieger"]'::jsonb, 2, 'Guanarteme war der Titel der Herrscher von Gáldar und Telde – also „König“ der Inselhälften.'),
('island', 8, 'Wie hieß Gran Canaria bei den Römern?', '["Insula Fortunata", "Nivaria", "Tamarán", "Canaria"]'::jsonb, 3, 'Plinius nannte die Insel „Canaria“ – vermutlich wegen der großen Hunde (canes).'),
('island', 8, 'Welche Kanareninsel heißt „die Schöne“?', '["La Palma", "La Gomera", "Teneriffa", "El Hierro"]'::jsonb, 0, 'La Palma, auch „Isla Bonita“ – mit der Caldera de Taburiente.'),
('island', 8, 'Was ist der „Pico de las Nieves“ wörtlich?', '["Berg der Wolken", "Schneegipfel", "Steinberg", "Berg der Winde"]'::jsonb, 1, '„Schnee“-Gipfel – hier lag im Winter am meisten Schnee, der im 17. Jahrhundert in Schneegruben gesammelt und nach Las Palmas gebracht wurde.'),
('island', 8, 'Wie hieß der letzte Vulkanausbruch der Insel?', '["Cumbre Vieja", "Teide", "Bandama", "Timanfaya"]'::jsonb, 2, 'Der Ausbruch, der die Caldera de Bandama formte, liegt rund 2.000 Jahre zurück.'),
('island', 8, 'Welcher Ort ist für seine Töpferei bekannt?', '["Arinaga", "Temisas", "Maspalomas", "La Atalaya de Santa Brígida"]'::jsonb, 3, 'In La Atalaya wird bis heute ohne Töpferscheibe gearbeitet – eine Tradition aus der Zeit vor der Eroberung.'),
('island', 9, 'Welcher Fink lebt nur im Kiefernwald von Inagua?', '["Buchfink", "Gran-Canaria-Teydefink", "Grünfink", "Stieglitz"]'::jsonb, 1, 'Der Blaufink (Gran-Canaria-Teydefink) brütet fast nur in den Kiefernwäldern von Inagua – Bestand im niedrigen dreistelligen Bereich.'),
('island', 9, 'Wie heißt der Lorbeerwald der feuchten Nordhänge?', '["Monteverde", "Pinar", "Laurisilva", "Fayal"]'::jsonb, 2, 'Laurisilva – ein Relikt des Tertiärs, das auf den Kanaren die Eiszeit überlebt hat.'),
('island', 9, 'Welcher Baum ist das Symbol der kanarischen Flora?', '["Zypresse", "Olivenbaum", "Kastanie", "Drachenbaum"]'::jsonb, 3, 'Dracaena draco – sein rotes Harz galt als „Drachenblut“ und wurde als Heilmittel gehandelt.'),
('island', 9, 'Woher stammt der Feigenkaktus der Insel?', '["Aus Mexiko", "Aus Marokko", "Aus Spanien", "Aus Indien"]'::jsonb, 0, 'Er kam nach 1492 aus Amerika – und mit ihm die Cochenille-Schildlaus.'),
('island', 9, 'Welche Wolkenformation liegt oft über dem Norden?', '["Calima", "Mar de nubes", "Bruma seca", "Nube baja"]'::jsonb, 1, 'Ein „Meer aus Wolken“, das sich am Passat staut und den Norden feucht hält.'),
('island', 9, 'Wie schützt sich die Kanarische Kiefer gegen Feuer?', '["Sie wächst nur im Regen", "Ihre Nadeln brennen nicht", "Dicke Rinde", "Sie speichert Wasser"]'::jsonb, 2, 'Die dicke Rinde isoliert die Knospen; nach einem Brand treibt der Baum aus dem Stamm neu aus.'),
('island', 9, 'Wann ist die beste Zeit zum Wandern im Bergland?', '["Juli und August", "Dezember und Januar", "Nur nach Regen", "Frühling und Herbst"]'::jsonb, 3, 'Frühling und Herbst – im Sommer ist es im Süden sehr heiß, im Winter kann es oben kalt und windig sein.'),
('island', 9, 'Was ist ein „tajinaste“?', '["Eine Pflanze mit Blütenkerze", "Ein Tanz", "Ein Werkzeug", "Ein Vogel"]'::jsonb, 0, 'Natternkopf-Arten (Echium) mit hohen Blütenständen – auf Gran Canaria mehrere endemische Arten.'),
('island', 9, 'Warum gibt es so viele endemische Arten?', '["Weil die Insel groß ist", "Weil die Insel lange isoliert war", "Weil es viel regnet", "Weil es keine Menschen gab"]'::jsonb, 1, 'Isolation über Millionen Jahre bei großer Höhenvielfalt – daraus entstanden eigene Arten.'),
('island', 9, 'Welche Gefahr bedroht die Wälder im Sommer am meisten?', '["Schnee", "Sturmflut", "Waldbrand", "Erdbeben"]'::jsonb, 2, 'Dürre und Hitze machen die Kiefernwälder anfällig; die Feuerwehr rechnet mit jedem Sommer.'),
('island', 9, 'Wie hoch reicht der Kiefernwald?', '["Bis 400 m", "Bis 1.000 m", "Bis zum Gipfel", "Bis 2.000 m"]'::jsonb, 3, 'Von etwa 800 bis knapp 2.000 Metern – darüber nur noch Ginster und Fels.'),
('island', 9, 'Welches Tier der Küste kann man vom Boot aus sehen?', '["Wale und Delfine", "Pinguine", "Robben", "Seeotter"]'::jsonb, 0, 'Vor der Südwestküste leben Große Tümmler und Rundkopfdelfine ganzjährig.'),
('island', 10, 'Wie heißt das kanarische Dessert aus Eigelb, Mandeln und Sirup?', '["Tarta de Santiago", "Flan", "Bienmesabe", "Turrón"]'::jsonb, 2, 'Bienmesabe – „schmeckt mir gut“ – wird kalt gelöffelt oder als Brotaufstrich gegessen.'),
('island', 10, 'Welcher Eintopf aus Fisch ist typisch kanarisch?', '["Paella", "Cocido", "Fabada", "Sancocho"]'::jsonb, 3, 'Sancocho – mit Salzwasserfisch, Kartoffeln und Mojo; auf den Kanaren ein Festtagsessen.'),
('island', 10, 'Was ist „ropa vieja“?', '["Ein Eintopf mit Fleisch und Kichererbsen", "Ein Nachtisch", "Ein Kleidungsstück", "Ein Salat"]'::jsonb, 0, 'Wörtlich „alte Kleider“ – ein Eintopf aus Rind- oder Schweinefleisch, Kichererbsen und Tomate.'),
('island', 10, 'Was ist „ron miel“?', '["Ein Wein", "Rum mit Honig", "Ein Käse", "Ein Kuchen"]'::jsonb, 1, 'Honigrum – ein Likör aus Rum und kanarischem Honig, sehr süß.'),
('island', 10, 'Von welcher Insel kommt „almogrote“?', '["Lanzarote", "Gran Canaria", "La Gomera", "El Hierro"]'::jsonb, 2, 'Ein Aufstrich aus gereiftem Käse, Paprika und Olivenöl – klassisch von La Gomera.'),
('island', 10, 'Welche Rebsorte ist typisch für die kanarischen Rotweine?', '["Tempranillo", "Merlot", "Rioja", "Listán Negro"]'::jsonb, 3, 'Listán Negro – eine alte, fast nur hier angebaute Sorte.'),
('island', 10, 'Was ist „miel de palma“?', '["Palmhonig", "Palmwein", "Palmzucker", "Palmöl"]'::jsonb, 0, 'Ein Sirup, der aus dem Saft der Kanarischen Palme gekocht wird – vor allem auf La Gomera.'),
('island', 10, 'Wann feiert man den Karneval auf der Insel?', '["Im Dezember", "Im Februar", "Im Oktober", "Im Juli"]'::jsonb, 1, 'Der Karneval liegt im Februar, die großen Umzüge finden in Las Palmas statt.'),
('island', 10, 'Was aßen die Ureinwohner als Grundnahrungsmittel?', '["Kartoffeln", "Reis", "Gofio", "Mais"]'::jsonb, 2, 'Gofio aus geröstetem Weizen oder Gerste – Kartoffeln und Mais kamen erst nach 1492.'),
('island', 10, 'Was ist „queso de flor“?', '["Ein Blumenstrauß", "Ein Likör", "Ein Kuchen", "Käse mit Distelblüte"]'::jsonb, 3, 'Der Labersatz stammt aus der Blüte der Artischockendistel – daher der Name und der feine Geschmack.'),
('island', 10, 'Welcher Fisch ist auf den Kanaren eine Spezialität?', '["Vieja", "Kabeljau", "Hering", "Lachs"]'::jsonb, 0, 'Die Vieja (Papageifisch) – meist gebraten mit Mojo, manchmal mit Knochen serviert.'),
('island', 10, 'Was trinkt man traditionell zum Kaffee dazu?', '["Ein Glas Milch", "Ein kleiner Schnaps", "Ein Bier", "Tee"]'::jsonb, 1, 'Ein „chupito“ – oft Ron miel oder ein Kräuterschnaps, häufig aufs Haus.'),
('island', 11, 'Wie viele große Eruptionsphasen durchlief die Insel?', '["Sieben", "Zwei", "Fünf", "Drei"]'::jsonb, 3, 'Ciclo I (alte Basalte), Ciclo II (Roque-Nublo-Formation) und Ciclo III (die jüngeren Vulkanbauten im Norden).'),
('island', 11, 'Welcher Berg gab der zweiten Eruptionsphase den Namen?', '["Roque Nublo", "Teide", "Bandama", "Pico de las Nieves"]'::jsonb, 0, 'Die „Roque-Nublo-Formation“ prägt weite Teile des Inselinneren – mit mächtigen Brekzien und Lavaströmen.'),
('island', 11, 'Wie breit ist die Caldera de Tejeda?', '["5 km", "15 km", "30 km", "50 km"]'::jsonb, 1, 'Rund 15 Kilometer – ein eingebrochener Vulkankessel, in dem Tejeda und Artenara liegen.'),
('island', 11, 'Was ist die Caldera de Bandama geologisch?', '["Ein Karstloch", "Ein Schildvulkan", "Ein Maar", "Ein Kratersee"]'::jsonb, 2, 'Ein Maar – ein Explosionskrater, entstanden als Magma auf Grundwasser traf.'),
('island', 11, 'Wie entsteht ein Maar?', '["Durch einen Meteoriten", "Durch Erosion", "Durch ein Erdbeben", "Magma trifft auf Grundwasser und verdampft explosionsartig"]'::jsonb, 3, 'Das Wasser verdampft schlagartig, der Druck sprengt einen Trichter – daher die steilen Wände.'),
('island', 11, 'Wo liegen die ältesten Gesteine der Insel?', '["Im Südwesten", "Im Norden", "Im Osten", "Auf dem Gipfel"]'::jsonb, 0, 'Im Südwesten um La Aldea und Güigüí – dort ist die Insel am ältesten.'),
('island', 11, 'Wie viele Mikroklimazonen hat Gran Canaria?', '["4", "14", "7", "21"]'::jsonb, 1, '14 – deshalb der Beiname „Kontinent im Miniaturformat“.'),
('island', 11, 'Welche Winde bestimmen das Wetter?', '["Mistral", "Bora", "Passatwinde", "Scirocco"]'::jsonb, 2, 'Die Passatwinde (alisios) wehen aus Nordost und teilen die Insel in feuchten Norden und trockenen Süden.'),
('island', 11, 'Wie lang ist die Küstenlinie der Insel?', '["500 km", "120 km", "380 km", "236 km"]'::jsonb, 3, 'Rund 236 Kilometer – bei nur 50 Kilometern Durchmesser.'),
('island', 11, 'Wie weit ist es von Gran Canaria bis nach Marokko?', '["210 km", "80 km", "400 km", "700 km"]'::jsonb, 0, 'Etwa 210 Kilometer bis zur afrikanischen Küste.'),
('island', 11, 'Was ist ein „malpaís“?', '["Ein schlechtes Land", "Ein Lavafeld", "Ein Sumpf", "Ein Weinberg"]'::jsonb, 1, 'Wörtlich „schlechtes Land“ – eine raue Lavalandschaft, auf der kaum etwas wächst.'),
('island', 11, 'Warum gibt es auf der Insel keine echten Flüsse?', '["Es regnet nicht", "Das Wasser verdunstet sofort", "Das Wasser versickert im porösen Vulkangestein", "Die Täler sind zu steil"]'::jsonb, 2, 'Das Regenwasser verschwindet im Gestein und tritt weiter unten wieder aus – deshalb die vielen Trockentäler.'),
('island', 12, 'Seit wann haben die Kanaren eine eigene Autonomie?', '["1982", "1978", "1931", "1992"]'::jsonb, 0, 'Das Autonomiestatut trat 1982 in Kraft; die erste Regionalregierung wurde 1983 gewählt.'),
('island', 12, 'Wann trat Spanien der Europäischen Gemeinschaft bei?', '["1975", "1986", "1992", "2004"]'::jsonb, 1, '1986 – die Kanaren kamen mit einem Sonderstatus dazu, der bis heute gilt.'),
('island', 12, 'Welche Steuer gilt auf den Kanaren statt der Mehrwertsteuer?', '["IVA", "IRPF", "IGIC", "ITP"]'::jsonb, 2, 'Der IGIC (Impuesto General Indirecto Canario) – niedriger als die spanische IVA.'),
