-- ── Quiz: Gran Canaria (270 Fragen, 18 pro Stufe) ──────────────────────────────────────────────────
-- Quelle: quiz/questions-island.json (dort pflegen, hier generieren).
-- Idempotent: gleicher Fragetext im gleichen Modus = Update.

on conflict (mode, question) do update
set step = excluded.step,
    options = excluded.options,
    correct = excluded.correct,
    explanation = excluded.explanation,
    active = true;
